css:
.landing-gimpo {
  --bg: #f7f4ef;
  --surface: #ffffff;
  --text: #1c1c1c;
  --muted: #5c5c5c;
  --accent: #c9a962;
  --accent-light: #e8d5a8;
  --accent-soft: #faf6ee;
  --accent-hover: #b8923a;
  --dark: #141414;
  --border: #e8dfd0;
  --header-bg: rgba(20,20,20,0.96);
  --header-text: #ffffff;
  --hero-overlay: linear-gradient(180deg, rgba(20,20,20,0.75) 0%, rgba(42,36,24,0.65) 100%);
  --font-serif: 'Cormorant Garamond', 'Noto Serif KR', Georgia, serif;
  --font-sans: 'Montserrat', 'Noto Sans KR', sans-serif;
  --btn-radius: 2px;
  --img-radius: 4px;
  --btn-primary-bg: #c9a962;
  --btn-primary-text: #141414;
  --btn-outline-bg: #ffffff;
  --btn-outline-text: #141414;
  --btn-top-bg: #c9a962;
  --btn-top-text: #141414;
  --btn-call-bg: #2a2a2a;
  --btn-call-text: #ffffff;
  --btn-sticky-cta-bg: #c9a962;
  --btn-sticky-cta-text: #141414;
}
.landing-gimpo .sticky-action-bar { background: rgba(20,20,20,0.97); border-top: 1px solid #3a3a3a; }
.landing-gimpo .sticky-action-bar .btn-call { background: var(--btn-call-bg); color: var(--btn-call-text); border: 1px solid #555; }
.landing-gimpo .sticky-action-bar .btn-cta { background: var(--btn-sticky-cta-bg); color: var(--btn-sticky-cta-text); }

.lp-root { min-height: 100vh; background: var(--bg); color: var(--text); font-family: var(--font-sans); line-height: 1.7; }
.lp-root img { max-width: 100%; height: auto; display: block; }
.lp-root a { text-decoration: none; color: inherit; transition: opacity 0.25s, color 0.25s; }
.lp-root a:hover { opacity: 0.88; }

.lp-header {
  position: sticky; top: 0; z-index: 100;
  background: var(--header-bg); backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--border);
}
.lp-header-inner {
  max-width: 1200px; margin: 0 auto; padding: 0.75rem 1.5rem;
  display: flex; align-items: center; justify-content: space-between; gap: 1rem;
}
.lp-brand { display: flex; flex-direction: column; line-height: 1.25; flex-shrink: 0; }
.lp-brand-sub { font-size: 0.65rem; letter-spacing: 0.18em; text-transform: uppercase; color: var(--accent); font-weight: 600; }
.lp-brand-main { font-family: var(--font-serif); font-size: 1.05rem; font-weight: 500; color: var(--header-text); }
.lp-nav { display: flex; flex-wrap: wrap; align-items: center; justify-content: center; gap: 0.35rem 1.1rem; flex: 1; }
.lp-nav a { font-size: 0.82rem; font-weight: 500; color: var(--header-text); opacity: 0.88; white-space: nowrap; }
.lp-nav a:hover { color: var(--accent); opacity: 1; }
.lp-nav-check { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0,0,0,0); border: 0; }
.lp-nav-toggle {
  display: none; align-items: center; justify-content: center;
  width: 2.5rem; height: 2.5rem; padding: 0; border: 1px solid var(--border);
  border-radius: var(--btn-radius); background: var(--surface); cursor: pointer; flex-shrink: 0;
}
.lp-nav-toggle-bar, .lp-nav-toggle-bar::before, .lp-nav-toggle-bar::after {
  display: block; width: 1.15rem; height: 2px; background: var(--header-text); border-radius: 1px; position: relative;
}
.lp-nav-toggle-bar::before, .lp-nav-toggle-bar::after { content: ""; position: absolute; left: 0; }
.lp-nav-toggle-bar::before { top: -6px; }
.lp-nav-toggle-bar::after { top: 6px; }
.lp-top-cta {
  font-size: 0.82rem; font-weight: 700; color: var(--btn-top-text, #fff);
  background: var(--btn-top-bg, var(--accent)); padding: 0.55rem 1rem; border-radius: var(--btn-radius);
  white-space: nowrap; flex-shrink: 0;
}
.lp-top-cta:hover { opacity: 0.92; color: var(--btn-top-text, #fff); }

.lp-hero { position: relative; min-height: clamp(420px, 72vh, 640px); display: flex; align-items: flex-end; overflow: hidden; }
.lp-hero-bg {
  position: absolute; inset: 0; background-size: cover; background-position: center;
}
.lp-hero-content {
  position: relative; z-index: 1; max-width: 1200px; margin: 0 auto; padding: 3rem 1.5rem 3.5rem;
  color: #fff; width: 100%;
  text-shadow: 0 2px 16px rgba(0,0,0,0.65), 0 1px 4px rgba(0,0,0,0.45);
}
.lp-hero-badge {
  display: inline-block; font-size: 0.72rem; font-weight: 600; letter-spacing: 0.22em;
  text-transform: uppercase; color: #fff; margin-bottom: 1rem;
}
.lp-hero-area { font-size: 0.9rem; color: rgba(255,255,255,0.92); margin-bottom: 0.5rem; }
.lp-hero h1 {
  font-family: var(--font-serif); font-size: clamp(2rem, 5vw, 3.2rem);
  font-weight: 400; line-height: 1.2; margin: 0 0 1rem; max-width: 720px;
}
.lp-hero h1 em { font-style: italic; color: #fff; }
.lp-hero-lead { font-size: 1.02rem; line-height: 1.85; max-width: 580px; color: rgba(255,255,255,0.95); margin: 0 0 1.75rem; }
.lp-hero-actions { display: flex; flex-wrap: wrap; gap: 0.75rem; }
.lp-btn {
  display: inline-block; padding: 0.85rem 1.6rem; font-weight: 600; font-size: 0.88rem;
  border-radius: var(--btn-radius); letter-spacing: 0.04em;
  text-shadow: none;
}
.lp-root a.lp-btn-primary {
  background: var(--btn-primary-bg, var(--accent));
  color: var(--btn-primary-text, #fff);
}
.lp-root a.lp-btn-outline {
  background: var(--btn-outline-bg, rgba(255,255,255,0.95));
  color: var(--btn-outline-text, var(--dark));
  border: none;
}
.lp-root a.lp-btn-primary:hover {
  opacity: 0.92;
  color: var(--btn-primary-text, #fff);
}
.lp-root a.lp-btn-outline:hover {
  opacity: 0.92;
  color: var(--btn-outline-text, var(--dark));
}
.lp-top-cta:hover { opacity: 0.92; color: var(--btn-top-text, #fff); }

.lp-container { max-width: 1200px; margin: 0 auto; padding: 0 1.5rem; }
.lp-section { padding: clamp(3rem, 6vw, 5rem) 0; scroll-margin-top: 80px; }
.lp-section-alt { background: var(--surface); }
.lp-section-label {
  font-size: 0.72rem; font-weight: 600; letter-spacing: 0.25em; text-transform: uppercase;
  color: var(--accent); margin-bottom: 0.75rem;
}
.lp-section-title {
  font-family: var(--font-serif); font-size: clamp(1.75rem, 3.5vw, 2.6rem);
  font-weight: 400; line-height: 1.25; margin: 0 0 1rem;
}
.lp-section-title em { font-style: italic; color: var(--accent); }
.lp-section-desc { color: var(--muted); max-width: 560px; line-height: 1.85; }

.lp-about-grid {
  display: grid; grid-template-columns: 1fr 1fr; gap: clamp(2rem, 4vw, 4rem); align-items: center;
}
.lp-about-image {
  border-radius: var(--img-radius); overflow: hidden; box-shadow: 0 20px 50px rgba(0,0,0,0.12);
  aspect-ratio: 4/5; object-fit: cover; width: 100%;
}
.lp-nearby {
  margin-top: 1.25rem; padding: 1rem 1.2rem; background: var(--accent-soft);
  border-radius: var(--img-radius); font-size: 0.92rem; color: var(--text);
}
.lp-nearby strong { color: var(--accent); display: block; margin-bottom: 0.5rem; }
.lp-nearby-tags { display: flex; flex-wrap: wrap; gap: 0.4rem; }
.lp-nearby-tag {
  display: inline-block; padding: 0.3rem 0.65rem; font-size: 0.82rem;
  background: var(--surface); border: 1px solid var(--border); border-radius: 999px; color: var(--muted);
}

.lp-regions-bar {
  background: var(--surface); border-bottom: 1px solid var(--border);
  padding: 0.85rem 0; scroll-margin-top: 80px;
}
.lp-regions-label {
  margin: 0 0 0.65rem; font-size: 0.82rem; font-weight: 600; color: var(--muted);
}
.lp-regions-label span { color: var(--accent); }
.lp-regions-scroll {
  display: flex; gap: 0.5rem; overflow-x: auto; padding-bottom: 0.25rem;
  -webkit-overflow-scrolling: touch; scrollbar-width: none;
}
.lp-regions-scroll::-webkit-scrollbar { display: none; }
.lp-region-chip {
  flex: 0 0 auto; display: inline-block; padding: 0.55rem 1rem;
  font-size: 0.84rem; font-weight: 600; border-radius: 999px;
  background: var(--btn-primary-bg, var(--accent));
  color: var(--btn-primary-text, #fff);
  border: 1px solid transparent; white-space: nowrap;
}
.lp-region-chip:hover { opacity: 0.9; color: var(--btn-primary-text, #fff); }
.lp-region-chip.is-current {
  background: var(--surface); color: var(--text);
  border-color: var(--border); pointer-events: none;
}

.lp-features { display: grid; grid-template-columns: repeat(3, 1fr); gap: 1.25rem; }
.lp-feature-card {
  background: var(--surface); border: 1px solid var(--border); border-radius: var(--img-radius);
  overflow: hidden; box-shadow: 0 8px 30px rgba(0,0,0,0.05);
}
.lp-feature-img { width: 100%; aspect-ratio: 4/3; object-fit: cover; }
.lp-feature-body { padding: 1.25rem 1.35rem 1.5rem; }
.lp-feature-num {
  font-size: 0.7rem; font-weight: 700; letter-spacing: 0.15em; color: var(--accent); margin-bottom: 0.5rem;
}
.lp-feature-body h3 { font-size: 1.05rem; margin: 0; font-weight: 600; }

.lp-gallery-grid {
  display: grid; grid-template-columns: repeat(5, 1fr); gap: 12px;
}
.lp-gallery-item {
  aspect-ratio: 1; overflow: hidden; border-radius: var(--img-radius);
  border: 1px solid var(--border); background: var(--surface);
}
.lp-gallery-item img {
  width: 100%; height: 100%; object-fit: cover; display: block;
}

.lp-reviews-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 1.25rem; }
.lp-review-card {
  background: var(--surface); border: 1px solid var(--border); border-radius: var(--img-radius);
  padding: 1.5rem 1.4rem; position: relative;
}
.lp-review-card::before {
  content: "\201C"; font-family: var(--font-serif); font-size: 3rem; line-height: 1;
  color: var(--accent); opacity: 0.35; position: absolute; top: 0.5rem; left: 1rem;
}
.lp-review-card p { margin: 1.5rem 0 1rem; font-size: 0.95rem; line-height: 1.75; color: var(--text); }
.lp-review-card footer { font-size: 0.82rem; color: var(--muted); }
.lp-review-card footer span { display: block; color: var(--accent); margin-top: 0.2rem; font-weight: 500; }

.lp-faq-list { max-width: 820px; }
.lp-faq-item { border-bottom: 1px solid var(--border); padding: 1.25rem 0; }
.lp-faq-item:first-child { border-top: 1px solid var(--border); }
.lp-faq-item h3 { font-size: 1rem; margin: 0 0 0.45rem; font-weight: 600; }
.lp-faq-item p { margin: 0; color: var(--muted); line-height: 1.75; font-size: 0.94rem; }

.lp-footer {
  background: var(--dark); color: rgba(255,255,255,0.55); text-align: center;
  padding: 2.5rem 1.5rem; font-size: 0.85rem;
}
.lp-root.has-sticky-bar { padding-bottom: calc(84px + env(safe-area-inset-bottom)); }

@media (max-width: 900px) {
  .lp-header-inner {
    flex-wrap: wrap; align-items: center; gap: 0.5rem 0.65rem;
    padding: 0.65rem 1rem;
  }
  .lp-brand { max-width: calc(100% - 7.5rem); min-width: 0; }
  .lp-brand-main { font-size: 0.95rem; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
  .lp-nav-toggle { display: inline-flex; margin-left: auto; order: 2; }
  .lp-top-cta { order: 3; font-size: 0.72rem; padding: 0.48rem 0.75rem; max-width: 6.5rem; overflow: hidden; text-overflow: ellipsis; }
  .lp-nav {
    order: 4; flex: 1 0 100%; width: 100%;
    display: none; flex-direction: column; align-items: stretch; gap: 0;
    max-height: 0; overflow: hidden; padding: 0;
    border-top: 0 solid var(--border); transition: max-height 0.25s ease, padding 0.25s ease;
  }
  .lp-nav a {
    padding: 0.75rem 0.15rem; border-bottom: 1px solid var(--border);
    font-size: 0.88rem; white-space: normal;
  }
  .lp-header-inner:has(.lp-nav-check:checked) .lp-nav {
    display: flex; max-height: 320px; padding: 0.35rem 0 0.15rem;
    border-top-width: 1px;
  }
  .lp-header-inner:has(.lp-nav-check:checked) .lp-nav-toggle { border-color: var(--accent); }
  .lp-about-grid, .lp-features, .lp-reviews-grid { grid-template-columns: 1fr; }
  .lp-gallery-grid { grid-template-columns: repeat(2, 1fr); }
  .lp-section { scroll-margin-top: 72px; }
}
@media (max-width: 520px) {
  .lp-gallery-grid { grid-template-columns: 1fr; }
}

.sticky-action-bar {
  position: fixed; bottom: 0; left: 0; right: 0; z-index: 1000;
  display: flex; gap: 8px; padding: 10px 12px;
  padding-bottom: max(10px, env(safe-area-inset-bottom));
  background: rgba(255,255,255,0.97);
  border-top: 1px solid #ddd;
  box-shadow: 0 -4px 24px rgba(0,0,0,0.12);
}
.sticky-action-bar a {
  flex: 1; text-align: center; padding: 13px 10px; border-radius: 8px;
  text-decoration: none; font-weight: 700; font-size: 0.92rem;
  font-family: "Noto Sans KR", "Segoe UI", sans-serif;
}
.sticky-action-bar .btn-call { background: var(--btn-call-bg, #2563eb); color: var(--btn-call-text, #fff); }
.sticky-action-bar .btn-cta { background: var(--btn-sticky-cta-bg, #0f172a); color: var(--btn-sticky-cta-text, #fff); }
